    def parse_version(version):
        # Match the pattern: YEAR.MONTH.PATCH[-hotfixN]?[+ci.N]?
        # Example: 2026.11.3, 2026.11.3-hotfix2, 2026.11.3+ci.41, 2026.11.3-hotfix2+ci.41
        match = re.match(r'(\d+)\.(\d+)\.(\d+)(?:\-(hotfix)(\d+))?(?:\+(ci)(\d+))?', version)
