        if match.group(4):
            hotfix = int(match.group(5))
        if match.group(6):
            ci = int(match.group(6))

        # Convert to comparable tuple: (year, month, patch, hotfix, ci)
        # Hotfix and ci are only used to break ties, with higher values being newer
        return (int(year), int(month), int(patch), hotfix or 0, ci or 0)

