def parse_rows(text):
    import csv
    import datetime as dt

    # Parse the tab-separated text into rows
    rows = list(csv.DictReader(io.StringIO(text), delimiter='\t'))

    def convert_value(value):
        v = value.strip()
        if v == '':
            return v

        # Remove commas from numbers (like 1,250 -> 1250)
        s = v.replace(',', '')

        # Whole numbers (e.g., "250") become int
        if re.fullmatch(r"-?\d+", s):
            return int(s)

        # Decimal numbers (e.g., "2.5") become float
        if re.fullmatch(r"-?\d+\.\d+", s):
            return float(s)

        # ISO date format (e.g., "2023-10-05") becomes datetime.date
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", v):
            return dt.date.fromisoformat(v)

        # Otherwise, keep as string
        return v

    # Convert each row's values to appropriate types
    result = []
    for row in rows:
        converted_row = {}
        for key, value in row.items():
            converted_row[key] = convert_value(value)
        result.append(converted_row)

    return result
