    import csv
    import datetime as dt

    # Split the text into rows
    rows = []
    for row in csv.reader(text.splitlines(), delimiter='\t'):
        if not row:
            continue
        # First row is headers
        if not rows:
            headers = row
        else:
            # Convert each field to appropriate type
            parsed_row = {}
            for i, value in enumerate(row):
                value = value.strip()
                # Handle weight: remove comma and convert to int if whole number
                if i == 2:  # qty_g column
                    value = value.replace(',', '')
                    if value.isdigit():
                        parsed_row[headers[i]] = int(value)
                    else:
                        parsed_row[headers[i]] = value
                elif i == 3:  # harvested column
                    try:
                        parsed_row[headers[i]] = dt.date.fromisoformat(value)
                    except ValueError:
                        parsed_row[headers[i]] = value
                else:
                    # accession and variety stay as text
                    parsed_row[headers[i]] = value
            rows.append(parsed_row)

    return rows
```

