import functools
import itertools

def retry_call(fn, attempts, sleep):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as e:
            if attempt == attempts - 1:
                raise
            sleep(1)  # sleep called with argument 1, as per the sleep function interface
```

```python
def unique_usernames(names):
    seen = set()
    result = []
    for name in names:
        if name not in seen:
            seen.add(name)
            result.append(name)
    return result
```
